import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentTimetable({ studentGrade = 'Grade 8' }) {
  const [timetableData, setTimetableData] = useState([]);
  const [loading, setLoading] = useState(true);

  const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  const dayHeaders = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  useEffect(() => {
    axios.get('http://localhost:8082/api/timetable')
      .then(res => {
        // ශිෂ්‍යයාගේ Grade එකට අදාළ දත්ත විතරක් තෝරාගැනීම
        const filtered = res.data.filter(item => item.grade === studentGrade);
        setTimetableData(filtered);
        setLoading(false);
      })
      .catch(err => {
        console.error("Error fetching timetable:", err);
        setLoading(false);
      });
  }, [studentGrade]);

  // 1. Database එකේ තියෙන Unique Time Slots විතරක් වෙන් කරගැනීම (Dynamic Rows)
  const uniqueTimeSlots = [...new Set(timetableData.map(item => item.time_slot))].filter(Boolean);

  // 2. අදාළ Day එකට සහ Time Slot එකට Match වෙන Class එක සෙවීම
  const getClassForSlot = (day, slot) => {
    return timetableData.find(item => 
      item.day.toLowerCase() === day.toLowerCase() && item.time_slot === slot
    );
  };

  if (loading) {
    return <div style={{ padding: '20px', color: '#64748b' }}>Loading timetable...</div>;
  }

  return (
    <div style={styles.card}>
      <h3 style={styles.title}>
        📅 Live Weekly Class Timetable ({studentGrade})
      </h3>

      <div style={{ overflowX: 'auto' }}>
        {/* පන්ති එකක්වත් ඇතුළත් කර නැතිනම් පෙන්වන Message එක */}
        {uniqueTimeSlots.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '40px 20px', color: '#64748b', backgroundColor: '#f8fafc', borderRadius: '8px' }}>
            🚫 No classes scheduled for {studentGrade} yet.
          </div>
        ) : (
          <table style={styles.table}>
            <thead>
              <tr>
                <th style={{ ...styles.th, width: '150px' }}>Time Slot</th>
                {dayHeaders.map((day, idx) => (
                  <th key={idx} style={styles.th}>{day}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {/* Admin ඇතුළත් කළ Time Slots විතරක් Rows ලෙස Render වේ */}
              {uniqueTimeSlots.map((slot, sIdx) => (
                <tr key={sIdx} style={styles.tr}>
                  <td style={styles.timeTd}>{slot}</td>

                  {days.map((day, dIdx) => {
                    const classItem = getClassForSlot(day, slot);

                    return (
                      <td key={dIdx} style={styles.td}>
                        {classItem ? (
                          <div style={styles.classBox}>
                            <div style={styles.subjectName}>{classItem.subject}</div>
                            <div style={styles.teacherName}>{classItem.teacher}</div>
                          </div>
                        ) : (
                          <span style={styles.dash}>-</span>
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

// 🎨 Styles
const styles = {
  card: { backgroundColor: '#ffffff', borderRadius: '12px', padding: '24px', boxShadow: '0 4px 20px rgba(0, 0, 0, 0.03)', margin: '20px' },
  title: { margin: '0 0 20px 0', color: '#1e293b', fontSize: '18px', fontWeight: '700' },
  table: { width: '100%', borderCollapse: 'collapse', fontSize: '13px' },
  th: { backgroundColor: '#f8fafc', color: '#64748b', fontWeight: '600', padding: '12px 8px', textAlign: 'center', borderBottom: '1px solid #e2e8f0' },
  tr: { borderBottom: '1px solid #f1f5f9' },
  timeTd: { padding: '16px 8px', fontWeight: '700', color: '#334155', textAlign: 'left', fontSize: '12px' },
  td: { padding: '12px 8px', textAlign: 'center', verticalAlign: 'middle' },
  dash: { color: '#cbd5e1', fontWeight: 'bold' },
  classBox: { backgroundColor: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: '6px', padding: '8px' },
  subjectName: { fontWeight: 'bold', color: '#15803d', fontSize: '12px' },
  teacherName: { color: '#64748b', fontSize: '11px', marginTop: '2px' }
};
